CREATE FUNCTION public.save_private_profile(_gender text,_other text,_dob date,_min integer DEFAULT NULL,_max integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _gender NOT IN('woman','man','non_binary','prefer_not_to_say') OR length(coalesce(_other,''))>100 THEN RAISE EXCEPTION 'Invalid private profile'; END IF; INSERT INTO public.profile_private(user_id,gender,gender_other,date_of_birth,meet_age_min,meet_age_max) VALUES(auth.uid(),_gender,_other,_dob,_min,_max) ON CONFLICT(user_id) DO UPDATE SET gender=excluded.gender,gender_other=excluded.gender_other,date_of_birth=excluded.date_of_birth; END $$; REVOKE ALL ON FUNCTION public.save_private_profile(text,text,date,integer,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_private_profile(text,text,date,integer,integer) TO authenticated;